```javascript
// Inventory System Module

class Item {
    constructor(name, weight, modifiers) {
        this.name = name;
        this.weight = weight;
        this.modifiers = modifiers || {};
    }
}

class Inventory {
    constructor(weightLimit) {
        this.weightLimit = weightLimit;
        this.items = [];
        this.equipmentSlots = {
            head: null,
            chest: null,
            hands: null,
            legs: null,
            feet: null
        };
    }

    addItem(item) {
        if (this.currentWeight() + item.weight > this.weightLimit) {
            console.log(`Cannot add ${item.name}. Weight limit exceeded.`);
            return false;
        }
        this.items.push(item);
        console.log(`${item.name} added to inventory.`);
        return true;
    }

    equipItem(slot, item) {
        if (!this.equipmentSlots[slot]) {
            console.log(`Invalid slot: ${slot}`);
            return false;
        }
        if (this.equipmentSlots[slot]) {
            console.log(`Unequipping ${this.equipmentSlots[slot].name} from ${slot}.`);
        }
        this.equipmentSlots[slot] = item;
        console.log(`${item.name} equipped in ${slot}.`);
        return true;
    }

    currentWeight() {
        return this.items.reduce((total, item) => total + item.weight, 0);
    }

    getStatModifiers() {
        const modifiers = { strength: 0, agility: 0, intelligence: 0 };
        for (const slot of Object.values(this.equipmentSlots)) {
            if (slot) {
                for (const [stat, value] of Object.entries(slot.modifiers)) {
                    modifiers[stat] += value;
                }
            }
        }
        return modifiers;
    }
}

// Self-Checking Demo

function runDemo() {
    const inventory = new Inventory(50);

    const sword = new Item('Sword', 10, { strength: 5 });
    const shield = new Item('Shield', 8, { defense: 3 });
    const helmet = new Item('Helmet', 5, { strength: 2, agility: 1 });
    const boots = new Item('Boots', 3, { agility: 2 });

    inventory.addItem(sword);
    inventory.addItem(shield);
    inventory.addItem(helmet);
    inventory.addItem(boots);

    inventory.equipItem('head', helmet);
    inventory.equipItem('chest', shield);
    inventory.equipItem('hands', sword);
    inventory.equipItem('feet', boots);

    console.log(`Current Weight: ${inventory.currentWeight()} / ${inventory.weightLimit}`);
    console.log('Stat Modifiers:', inventory.getStatModifiers());
}

runDemo();
```

### Explanation:
- **Item Class**: Represents an item with a name, weight, and optional modifiers.
- **Inventory Class**: Manages items and equipment slots. It checks weight limits and applies stat modifiers from equipped items.
- **runDemo Function**: Demonstrates adding items to the inventory and equipping them to slots, then logs the current weight and stat modifiers.

