```javascript
// CombatSystem.js

class Character {
    constructor(name, health, attack, defense, speed) {
        this.name = name;
        this.health = health;
        this.attack = attack;
        this.defense = defense;
        this.speed = speed;
        this.statusEffects = [];
    }

    takeDamage(amount) {
        const damage = Math.max(0, amount - this.defense);
        this.health -= damage;
        console.log(`${this.name} takes ${damage} damage. Health: ${this.health}`);
    }

    applyStatusEffect(effect) {
        if (!this.statusEffects.includes(effect)) {
            this.statusEffects.push(effect);
            console.log(`${this.name} is affected by ${effect}.`);
        }
    }

    removeStatusEffect(effect) {
        const index = this.statusEffects.indexOf(effect);
        if (index !== -1) {
            this.statusEffects.splice(index, 1);
            console.log(`${this.name} is no longer affected by ${effect}.`);
        }
    }

    hasStatusEffect(effect) {
        return this.statusEffects.includes(effect);
    }
}

class CombatSystem {
    constructor(characters) {
        this.characters = characters;
        this.initiativeOrder = [];
        this.round = 0;
    }

    calculateInitiative() {
        this.initiativeOrder = this.characters.slice().sort((a, b) => b.speed - a.speed);
    }

    startCombat() {
        this.calculateInitiative();
        console.log("Combat begins!");
        while (this.characters.some(char => char.health > 0)) {
            this.round++;
            console.log(`\nRound ${this.round}:`);
            for (const character of this.initiativeOrder) {
                if (character.health <= 0) continue;
                this.processTurn(character);
            }
        }
        this.endCombat();
    }

    processTurn(character) {
        if (character.hasStatusEffect('stun')) {
            console.log(`${character.name} is stunned and cannot act.`);
            character.removeStatusEffect('stun');
            return;
        }

        const target = this.getRandomTarget(character);
        if (!target) return;

        let damage = character.attack;
        if (character.hasStatusEffect('poison')) {
            damage += 5; // Additional damage from poison
        }

        target.takeDamage(damage);

        // Apply random status effect
        const statusEffects = ['poison', 'stun'];
        const effect = statusEffects[Math.floor(Math.random() * statusEffects.length)];
        target.applyStatusEffect(effect);
    }

    getRandomTarget(exclude) {
        const targets = this.characters.filter(char => char !== exclude && char.health > 0);
        return targets.length > 0 ? targets[Math.floor(Math.random() * targets.length)] : null;
    }

    endCombat() {
        const winner = this.characters.find(char => char.health > 0);
        console.log(`Combat ends. ${winner ? winner.name : 'No one'} wins!`);
    }
}

// Demo
const characters = [
    new Character('Hero', 100, 20, 10, 15),
    new Character('Monster', 80, 15, 5, 10)
];

const combatSystem = new CombatSystem(characters);
combatSystem.startCombat();
```

### Explanation:
- **Character Class**: Represents a character with attributes like health, attack, defense, and speed. It also manages status effects.
- **CombatSystem Class**: Manages the combat logic, including calculating initiative order, processing turns, and applying status effects.
- **Demo**: Creates two characters and starts the combat system to demonstrate its functionality.

