```javascript
// CraftingSystem.js

class CraftingSystem {
  constructor() {
    this.recipes = [];
    this.inventory = {};
  }

  // Add a recipe to the crafting system
  addRecipe(recipe) {
    this.recipes.push(recipe);
  }

  // Add items to the inventory
  addToInventory(item, quantity) {
    if (this.inventory[item]) {
      this.inventory[item] += quantity;
    } else {
      this.inventory[item] = quantity;
    }
  }

  // Check if a recipe can be crafted with the current inventory
  canCraft(recipe) {
    for (const [item, quantity] of Object.entries(recipe.requires)) {
      if (!this.inventory[item] || this.inventory[item] < quantity) {
        return false;
      }
    }
    return true;
  }

  // Craft an item if possible
  craft(recipe) {
    if (this.canCraft(recipe)) {
      for (const [item, quantity] of Object.entries(recipe.requires)) {
        this.inventory[item] -= quantity;
      }
      if (recipe.produces) {
        this.addToInventory(recipe.produces.item, recipe.produces.quantity);
      }
      return true;
    }
    return false;
  }

  // Display the current inventory
  displayInventory() {
    console.log("Current Inventory:");
    for (const [item, quantity] of Object.entries(this.inventory)) {
      console.log(`${item}: ${quantity}`);
    }
  }
}

// Self-checking demo
function runDemo() {
  const craftingSystem = new CraftingSystem();

  // Define some recipes
  const woodPickaxeRecipe = {
    name: "Wood Pickaxe",
    requires: { "Wood": 3, "Stick": 2 },
    produces: { item: "Wood Pickaxe", quantity: 1 }
  };

  const stonePickaxeRecipe = {
    name: "Stone Pickaxe",
    requires: { "Stone": 3, "Stick": 2 },
    produces: { item: "Stone Pickaxe", quantity: 1 }
  };

  // Add recipes to the crafting system
  craftingSystem.addRecipe(woodPickaxeRecipe);
  craftingSystem.addRecipe(stonePickaxeRecipe);

  // Add items to the inventory
  craftingSystem.addToInventory("Wood", 5);
  craftingSystem.addToInventory("Stick", 4);
  craftingSystem.addToInventory("Stone", 6);

  // Display initial inventory
  craftingSystem.displayInventory();

  // Attempt to craft a Wood Pickaxe
  console.log("\nAttempting to craft a Wood Pickaxe...");
  if (craftingSystem.craft(woodPickaxeRecipe)) {
    console.log("Successfully crafted a Wood Pickaxe!");
  } else {
    console.log("Failed to craft a Wood Pickaxe.");
  }

  // Display inventory after crafting
  craftingSystem.displayInventory();

  // Attempt to craft a Stone Pickaxe
  console.log("\nAttempting to craft a Stone Pickaxe...");
  if (craftingSystem.craft(stonePickaxeRecipe)) {
    console.log("Successfully crafted a Stone Pickaxe!");
  } else {
    console.log("Failed to craft a Stone Pickaxe.");
  }

  // Display final inventory
  craftingSystem.displayInventory();
}

// Run the demo
runDemo();
```

This code defines a `CraftingSystem` class with methods to add recipes, manage inventory, check if a recipe can be crafted, and perform the crafting action. The `runDemo` function sets up a simple scenario with two recipes and demonstrates the crafting process, including displaying the inventory before and after crafting attempts.

