```javascript
// gameSaveLoad.js

// Game state object
let gameState = {
  score: 0,
  level: 1,
  player: {
    name: "Player1",
    health: 100,
    inventory: ["sword", "shield"]
  }
};

// Function to save the game state to local storage
function saveGameState() {
  const gameStateString = JSON.stringify(gameState);
  localStorage.setItem('gameState', gameStateString);
  console.log("Game state saved.");
}

// Function to load the game state from local storage
function loadGameState() {
  const gameStateString = localStorage.getItem('gameState');
  if (gameStateString) {
    gameState = JSON.parse(gameStateString);
    console.log("Game state loaded.");
  } else {
    console.log("No saved game state found.");
  }
}

// Function to display the current game state
function displayGameState() {
  console.log("Current Game State:");
  console.log(`Score: ${gameState.score}`);
  console.log(`Level: ${gameState.level}`);
  console.log(`Player Name: ${gameState.player.name}`);
  console.log(`Health: ${gameState.player.health}`);
  console.log(`Inventory: ${gameState.player.inventory.join(", ")}`);
}

// Self-checking demo
function runDemo() {
  console.log("Starting game...");
  displayGameState();

  // Modify the game state
  gameState.score += 10;
  gameState.level++;
  gameState.player.health -= 20;
  gameState.player.inventory.push("potion");

  console.log("\nModified game state:");
  displayGameState();

  // Save the game state
  saveGameState();

  // Clear the game state
  gameState = {
    score: 0,
    level: 1,
    player: {
      name: "Player1",
      health: 100,
      inventory: ["sword", "shield"]
    }
  };

  console.log("\nCleared game state:");
  displayGameState();

  // Load the game state
  loadGameState();

  console.log("\nLoaded game state:");
  displayGameState();
}

// Run the demo
runDemo();
```

### Explanation:
- **Game State**: A simple object representing the game state with properties like `score`, `level`, and a nested `player` object.
- **saveGameState**: Serializes the `gameState` object to a JSON string and stores it in `localStorage`.
- **loadGameState**: Retrieves the JSON string from `localStorage`, parses it back into an object, and assigns it to `gameState`.
- **displayGameState**: Logs the current state of the game to the console.
- **runDemo**: Demonstrates the save and load functionality by modifying the game state, saving it, clearing it, and then loading it back to verify the data integrity.

