```javascript
// QuestSystem.js

class Quest {
    constructor(name, steps, reward) {
        this.name = name;
        this.steps = steps;
        this.reward = reward;
        this.currentStep = 0;
        this.completed = false;
    }

    completeStep() {
        if (this.currentStep < this.steps.length) {
            this.currentStep++;
            console.log(`Completed step ${this.currentStep} of ${this.steps.length}`);
        }
        if (this.currentStep === this.steps.length) {
            this.completeQuest();
        }
    }

    completeQuest() {
        this.completed = true;
        console.log(`Quest "${this.name}" completed! Reward: ${this.reward}`);
    }

    checkProgress() {
        console.log(`Quest: ${this.name}`);
        console.log(`Steps Completed: ${this.currentStep}/${this.steps.length}`);
        console.log(`Reward: ${this.completed ? this.reward : 'Not yet earned'}`);
    }
}

class QuestSystem {
    constructor() {
        this.quests = [];
    }

    addQuest(quest) {
        this.quests.push(quest);
    }

    completeQuestStep(questName) {
        const quest = this.quests.find(q => q.name === questName);
        if (quest) {
            quest.completeStep();
        } else {
            console.log(`Quest "${questName}" not found.`);
        }
    }

    checkQuestProgress(questName) {
        const quest = this.quests.find(q => q.name === questName);
        if (quest) {
            quest.checkProgress();
        } else {
            console.log(`Quest "${questName}" not found.`);
        }
    }
}

// Self-checking demo
const questSystem = new QuestSystem();

const quest1 = new Quest('Gather Ingredients', ['Find flour', 'Find eggs', 'Find sugar'], 'Cake');
const quest2 = new Quest('Defeat the Dragon', ['Find the dragon', 'Prepare for battle', 'Defeat the dragon'], 'Treasure');

questSystem.addQuest(quest1);
questSystem.addQuest(quest2);

console.log('Starting quests...');
questSystem.completeQuestStep('Gather Ingredients');
questSystem.completeQuestStep('Gather Ingredients');
questSystem.completeQuestStep('Gather Ingredients');

questSystem.completeQuestStep('Defeat the Dragon');
questSystem.completeQuestStep('Defeat the Dragon');
questSystem.completeQuestStep('Defeat the Dragon');

console.log('\nChecking quest progress...');
questSystem.checkQuestProgress('Gather Ingredients');
questSystem.checkQuestProgress('Defeat the Dragon');
```

### Explanation:
- **Quest Class**: Represents a single quest with a name, list of steps, and a reward. It tracks the current step and whether the quest is completed.
- **QuestSystem Class**: Manages multiple quests. It allows adding quests and completing steps of specific quests.
- **Self-checking Demo**: Demonstrates the functionality by creating two quests, completing their steps, and checking their progress.

