```javascript
// ShopEconomy.js

class ShopEconomy {
  constructor() {
    this.items = {
      apple: { price: 1.0, supply: 50, demand: 30 },
      banana: { price: 0.5, supply: 40, demand: 20 },
      orange: { price: 0.75, supply: 60, demand: 40 }
    };
  }

  updatePrices() {
    for (const item in this.items) {
      const { supply, demand } = this.items[item];
      const priceChange = (demand - supply) * 0.01;
      this.items[item].price += priceChange;
      this.items[item].price = Math.max(0.1, this.items[item].price); // Ensure price doesn't go below 0.1
    }
  }

  displayPrices() {
    console.log("Current Prices:");
    for (const item in this.items) {
      console.log(`${item}: $${this.items[item].price.toFixed(2)}`);
    }
  }

  simulateDay() {
    console.log("Simulating a day...");
    this.updatePrices();
    this.displayPrices();
  }
}

// Self-checking demo
const economy = new ShopEconomy();
economy.displayPrices(); // Initial prices
economy.simulateDay();   // Simulate one day
economy.simulateDay();   // Simulate another day
```

### Explanation:
- **ShopEconomy Class**: This class manages the items in the shop, their prices, supply, and demand.
- **Constructor**: Initializes the items with initial prices, supply, and demand.
