// statusEffectSystem.js

class StatusEffect {
    constructor(name, duration, onExpire) {
        this.name = name;
        this.duration = duration;
        this.onExpire = onExpire;
    }

    tick() {
        if (this.duration > 0) {
            this.duration--;
        } else {
            this.onExpire();
        }
    }
}

class StatusEffectManager {
    constructor() {
        this.effects = new Map();
    }

    addEffect(effect) {
        if (this.effects.has(effect.name)) {
            const existingEffect = this.effects.get(effect.name);
            existingEffect.duration = Math.max(existingEffect.duration, effect.duration);
        } else {
            this.effects.set(effect.name, effect);
        }
    }

    removeEffect(name) {
        this.effects.delete(name);
    }

    tickAll() {
        for (const effect of this.effects.values()) {
            effect.tick();
        }
    }

    getActiveEffects() {
        return Array.from(this.effects.values()).filter(effect => effect.duration > 0);
    }
}

// Self-checking demo
function demo() {
    const manager = new StatusEffectManager();

    const burnEffect = new StatusEffect('Burn', 3, () => console.log('Burn expired'));
    const poisonEffect = new StatusEffect('Poison', 2, () => console.log('Poison expired'));

    manager.addEffect(burnEffect);
    manager.addEffect(poisonEffect);

    console.log('Initial effects:', manager.getActiveEffects().map(e => e.name));

    for (let i = 0; i < 5; i++) {
        manager.tickAll();
        console.log(`After tick ${i + 1}:`, manager.getActiveEffects().map(e => `${e.name} (${e.duration})`));
    }
}

demo();
```

