function preload() {
    this.load.image('player', 'https://labs.phaser.io/assets/sprites/phaser2.png');
    this.load.image('bullet', 'https://labs.phaser.io/assets/sprites/bullet1.png');
    this.load.image('enemy', 'https://labs.phaser.io/assets/sprites/enemy.png');
}

function create() {
    // Create the player
    this.player = this.physics.add.sprite(400, 300, 'player').setOrigin(0.5);
    this.player.setCollideWorldBounds(true);

    // Create the bullet group
    this.bullets = this.physics.add.group({
        key: 'bullet',
        repeat: 10,
        setXY: { x: 0, y: 0, stepX: 10 }
    });

    // Create the enemy group
    this.enemies = this.physics.add.group();

    // Set up input
    this.input.on('pointerdown', shootBullet, this);

    // Spawn enemies at the edges
    this.time.addEvent({
        delay: 1000,
        callback: spawnEnemy,
        callbackScope: this,
        loop: true
    });
}

function update() {
    // Rotate the player towards the pointer
    const pointer = this.input.activePointer;
    if (pointer.isDown) {
        const angle = Phaser.Math.Angle.Between(this.player.x, this.player.y, pointer.x, pointer.y);
        this.player.rotation = angle;
    }

    // Update bullets
    this.bullets.children.iterate(bullet => {
        if (bullet.active && bullet.y < 0 || bullet.y > 600 || bullet.x < 0 || bullet.x > 800) {
            bullet.setActive(false);
            bullet.setVisible(false);
        }
    });

    // Check for collisions between bullets and enemies
    this.physics.overlap(this.bullets, this.enemies, handleCollision, null, this);
}

function shootBullet() {
    const bullet = this.bullets.get();
    if (bullet) {
        bullet.setActive(true);
        bullet.setVisible(true);
        bullet.setPosition(this.player.x, this.player.y);
        bullet.setRotation(this.player.rotation);
        bullet.setVelocity(Math.cos(this.player.rotation) * 500, Math.sin(this.player.rotation) * 500);
    }
}

function spawnEnemy() {
    const side = Phaser.Math.Between(0, 3);
    let x, y;

    switch (side) {
        case 0: // Top
            x = Phaser.Math.Between(0, 800);
            y = 0;
            break;
        case 1: // Right
            x = 800;
            y = Phaser.Math.Between(0, 600);
            break;
        case 2: // Bottom
            x = Phaser.Math.Between(0, 800);
            y = 600;
            break;
        case 3: // Left
            x = 0;
            y = Phaser.Math.Between(0, 600);
            break;
    }

    const enemy = this.enemies.create(x, y, 'enemy');
    enemy.setCollideWorldBounds(true);
    enemy.setVelocity(Phaser.Math.Between(-100, 100), Phaser.Math.Between(-100, 100));
}

function handleCollision(bullet, enemy) {
    bullet.setActive(false);
    bullet.setVisible(false);
    enemy.destroy();
}
