const game = new Phaser.Game(config);

let grid;
let selectedTile = null;
let tiles = [];
const gridSize = { rows: 8, cols: 8 };
const tileWidth = 50;
const tileHeight = 50;
const offsetX = 50;
const offsetY = 50;

function preload() {
    this.load.image('tile', 'path/to/tile.png'); // Replace with your tile image path
}

function create() {
    grid = createGrid();
    renderGrid();
}

function update() {
    if (selectedTile) {
        const pointer = this.input.activePointer;
        if (pointer.isDown && !pointer.wasDown) {
            const x = Math.floor((pointer.x - offsetX) / tileWidth);
            const y = Math.floor((pointer.y - offsetY) / tileHeight);
            if (x >= 0 && x < gridSize.cols && y >= 0 && y < gridSize.rows) {
                const tile = grid[y][x];
                if (isAdjacent(selectedTile, tile)) {
                    swapTiles(selectedTile, tile);
                    checkMatches();
                    selectedTile = null;
                }
            }
        }
    }
}

function createGrid() {
    const grid = [];
    for (let y = 0; y < gridSize.rows; y++) {
        const row = [];
        for (let x = 0; x < gridSize.cols; x++) {
            const color = Phaser.Display.Color.RandomRGB().color;
            const tile = this.add.image(offsetX + x * tileWidth, offsetY + y * tileHeight, 'tile');
            tile.setTint(color);
            tile.setInteractive();
            tile.on('pointerdown', () => selectTile(tile));
            row.push(tile);
        }
        grid.push(row);
    }
    return grid;
}

function renderGrid() {
    for (let y = 0; y < gridSize.rows; y++) {
        for (let x = 0; x < gridSize.cols; x++) {
            const tile = grid[y][x];
            tile.setPosition(offsetX + x * tileWidth, offsetY + y * tileHeight);
        }
    }
}

function selectTile(tile) {
    if (selectedTile === tile) {
        selectedTile = null;
    } else {
        selectedTile = tile;
    }
}

function isAdjacent(tile1, tile2) {
    const dx = Math.abs(tile1.x - tile2.x);
    const dy = Math.abs(tile1.y - tile2.y);
    return (dx === tileWidth && dy === 0) || (dx === 0 && dy === tileHeight);
}

function swapTiles(tile1, tile2) {
    const tempX = tile1.x;
    const tempY = tile1.y;
    tile1.setPosition(tile2.x, tile2.y);
    tile2.setPosition(tempX, tempY);
}

function checkMatches() {
    let matches = findMatches();
    while (matches.length > 0) {
        clearMatches(matches);
        dropTiles();
        fillEmptySpaces();
        matches = findMatches();
    }
}

function findMatches() {
    const matches = [];
    for (let y = 0; y < gridSize.rows; y++) {
        for (let x = 0; x < gridSize.cols; x++) {
            const tile = grid[y][x];
            const match = checkMatch(tile, x, y);
            if (match.length > 2) {
                matches.push(match);
            }
        }
    }
    return matches;
}

function checkMatch(tile, startX, startY) {
    const match = [tile];
    const color = tile.tint;
    let x = startX + 1;
    while (x < gridSize.cols && grid[startY][x].tint === color) {
        match.push(grid[startY][x]);
        x++;
    }
    x = startX - 1;
    while (x >= 0 && grid[startY][x].tint === color) {
        match.push(grid[startY][x]);
        x--;
    }
    let y = startY + 1;
    while (y < gridSize.rows && grid[y][startX].tint === color) {
        match.push(grid[y][startX]);
        y++;
    }
    y = startY - 1;
    while (y >= 0 && grid[y][startX].tint === color) {
        match.push(grid[y][startX]);
        y--;
    }
    return match;
}

function clearMatches(matches) {
    matches.forEach(tile => {
        tile.destroy();
    });
}

function dropTiles() {
    for (let x = 0; x < gridSize.cols; x++) {
        let emptyCount = 0;
        for (let y = gridSize.rows - 1; y >= 0; y--) {
            const tile = grid[y][x];
            if (!tile) {
                emptyCount++;
            } else {
                tile.y += emptyCount * tileHeight;
            }
        }
    }
}

function fillEmptySpaces() {
    for (let x = 0; x < gridSize.cols; x++) {
        for (let y = 0; y < gridSize.rows; y++) {
            if (!grid[y][x]) {
                const color = Phaser.Display.Color.RandomRGB().color;
                const tile = this.add.image(offsetX + x * tileWidth, offsetY + y * tileHeight, 'tile');
                tile.setTint(color);
                tile.setInteractive();
                tile.on('pointerdown', () => selectTile(tile));
                grid[y][x] = tile;
            }
        }
    }
}
